const adj=new Map<string,Set<string>>(),indegree=new Map<string,number>();for(const w of words)for(const c of w){adj.set(c,new Set());indegree.set(c,0);}for(let i=1;i<words.length;i++){const a=words[i-1],b=words[i];let j=0;while(j<Math.min(a.length,b.length)&&a[j]===b[j])j++;if(j===b.length&&a.length>b.length)return '';if(j<a.length&&j<b.length&&!adj.get(a[j])!.has(b[j])){adj.get(a[j])!.add(b[j]);indegree.set(b[j],indegree.get(b[j])!+1);}}let result='';const ready=[...indegree.keys()].filter(c=>indegree.get(c)===0);while(ready.length){ready.sort();const c=ready.shift()!;result+=c;for(const d of adj.get(c)!){indegree.set(d,indegree.get(d)!-1);if(indegree.get(d)===0)ready.push(d);}}return result.length===indegree.size?result:'';
